#include <map>

int main() {
    std::map<int, std::string> m = {{1, "One"}};
    auto it = m.begin();

    // OK: Value is mutable
    it->second = "Uno"; 

    // ERROR: Key is const and cannot be modified
    // it->first = 2; // Compilation error: assignment of read-only member

    // If a key must change, the original element must be erased
    // and a new element inserted with the new key.
    m.erase(it);
    m.insert({2, "Two"});
}
